    eras: [{ era: "modern", character: "Baddest Woman on the Planet", persona: "UFC's first female champion — legitimately the most dangerous woman to ever sign with WWE. Her debut at WM34 with The Rock was electric. Her in-ring competence in under two years of training was remarkable. Her second run generated more controversy — her comments about fans created lasting tension." }],
    championships: [{ title: "Raw Women's Championship", count: 1, reigns: [{ date: "Aug 2018" }], firstReign: "Aug 2018", notable: "Won at SummerSlam — her first title" }, { title: "SmackDown Women's Championship", count: 2, firstReign: "Apr 2022", notable: "Post-return title reigns" }],
